{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Hydrocortisone, the highest-transfer analogue, has an absolute oral bioavailability of 0.95 in healthy adults, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Amoxicillin, a high-transfer analogue, has an absolute bioavailability of 77.4% based on serum AUC versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Finasteride, a rigid polycyclic steroid-like analogue, has a mean absolute oral bioavailability of 63% (range 34–108%), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Methylprednisolone, a corticosteroid analogue, has an absolute oral bioavailability of 82% versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Naltrexone, the lowest-transfer analogue, has very poor oral bioavailability of about 5–10%, providing some contradictory evidence for low F, but its basic amine/phenol structure and lower transfer score reduce relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer and structurally relevant analogues—hydrocortisone, amoxicillin, finasteride, and methylprednisolone—consistently show absolute oral bioavailability well above 20%, often 60–95%. The only clearly low-F analogue, naltrexone, has the lowest transfer score and lacks the query's lactone-rich polycyclic features. Therefore, high oral bioavailability at the F ≥ 20% threshold is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record exists for the query molecule itself.",
    "All evidence is indirect, with assay-transfer scores below 0.8.",
    "Formulation-dependent effects on oral bioavailability (e.g., suspension vs tablet) are not fully captured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

